// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address token, address to, uint256 amount) public {
        vm.assume(token != address(0));
        vm.assume(token != address(c));
        vm.assume(to != address(0));
        vm.assume(to != address(c));
        SuccessToken s = new SuccessToken();
        address[] memory tos = new address[](1);
        uint[] memory vs = new uint[](1);
        tos[0] = to;
        vs[0] = amount;
        bool ok = c.transfer(address(s), tos, vs);
        assertTrue(ok);
    }
}

contract SuccessToken {
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
